mapper.insert:

/* com.kt.openapi.web.devsupport.dao.DevSupportDAO.saveForum */ 
INSERT INTO KOA_TB_DEVSUPPORT_BBS
   (TITLE
   ,SBST
   ,BBS_TYPE_CD
   ,IMPT_YN
   ,REG_DT
   ,REGR
   ,AMD_DT
   ,AMDR
   ,SHOW_YN
   ,RETV_NUM
   ,PSTING_NO
   ,DEVSUPPORT_GB
   ,SERVICEINFRA_NM
   ,SERVICE_BO
   ,SERVICE_DO
   ,ADC_ID
   ,SERVICE_CODE)
VALUES
   (#{title}
   ,#{sbst}
   ,#{bbsTypeCd}
   ,#{imptYn}
   ,NOW()
   ,#{regr}
   ,NOW()
   ,#{regr}
   ,'Y'
   ,0 
   ,(SELECT COALESCE(MAX(PSTING_NO ) , 1) FROM KOA_TB_DEVSUPPORT_BBS  WHERE BBS_TYPE_CD = #{bbsTypeCd}) + 1
   ,#{devSupport_GB}
   ,#{serviceInfra_NM}
   ,#{service_BO}
   ,#{service_DO}
   ,#{adcId}
   ,#{serviceCode}
   )

mapper.select:
/* com.kt.openapi.web.devsupport.dao.DevSupportDAO.selDevSupportListCnt */ 
SELECT
      COUNT(*) AS cnt
FROM KOA_TB_DEVSUPPORT_BBS 
WHERE 1=1

    AND BBS_TYPE_CD = #{bbsTypeCd}

/* com.kt.openapi.web.devsupport.dao.DevSupportDAO.selDevSupportVoView */ SELECT B.PSTING_ID ,B.TITLE ,B.SBST ,B.BBS_TYPE_CD ,B.IMPT_YN ,TO_CHAR(B.REG_DT, 'YYYY-MM-DD') AS REG_DT ,SUBSTRING(B.REGR, 0 , LENGTH(B.REGR)-2) + REPEAT('*', 3) AS REGR ,TO_CHAR(B.AMD_DT, 'YYYY-MM-DD') AS AMD_DT ,COALESCE(B.AMDR,'') AS AMDR ,'홍길순' AS REGRN ,B.DEVSUPPORT_GB SUPPORTGB ,B.SHOW_YN ,B.PREV_PSTING_ID ,B.NEXT_PSTING_ID ,B.PREV_TITLE ,B.NEXT_TITLE ,SERVICEINFRA_NM AS SERVINFRAN ,(SELECT USER_NM_C FROM T_USER_INFO AA WHERE AA.USER_SEQ = B.SERVICE_BO) AS BUSERN ,(SELECT USER_NM_C FROM T_USER_INFO AA WHERE AA.USER_SEQ = B.SERVICE_DO) AS DUSERN ,ADC_ID AS ADCI ,SERVICE_CODE AS SERVC ,STATUS ,COMMENT ,SERVICE_BO AS SERVBO ,SERVICE_DO AS SERVDO FROM ( SELECT A.* , LAG(A.PSTING_ID, 1, 0) OVER ( ORDER BY A.REG_DT DESC) AS PREV_PSTING_ID , LEAD(A.PSTING_ID, 1, 0) OVER ( ORDER BY A.REG_DT DESC) AS NEXT_PSTING_ID , LAG(A.TITLE, 1, '') OVER ( ORDER BY A.REG_DT DESC) AS PREV_TITLE , LEAD(A.TITLE, 1, '') OVER ( ORDER BY A.REG_DT DESC) AS NEXT_TITLE FROM KOA_TB_DEVSUPPORT_BBS A WHERE 1=1 AND SHOW_YN = 'Y'
AND IMPT_YN = #{imptYn}
AND BBS_TYPE_CD = #{bbsTypeCd}
) B WHERE 1=1
AND B.PSTING_ID = #{pstingId}

/* com.kt.openapi.web.devsupport.dao.DevSupportDAO.selDevSupportMyServiceList */ 
SELECT SERVICEINFRA_NM myServiceInfraNm
FROM KOA_TB_DEVSUPPORT_BBS 
WHERE SERVICEINFRA_NM IS NOT NULL 

    AND REGR = #{regr}

GROUP BY SERVICEINFRA_NM

/* com.kt.openapi.web.devsupport.dao.DevSupportDAO.selDevSupportManagerList */
SELECT ROW_NUMBER() OVER (ORDER BY REG_DT DESC) rownum, USER_SEQ, USER_ID_OLD, AUTH_SEQ, USER_NM_OLD, TEL_NO, EMAIL, DEP_NM, COMPANY_NM, COMPANY_TEL, COMPANY_EMAIL, USE_YN, DEL_YN, REG_DT, LOGIN_DT, USER_NM_D, USER_ID_D, USER_NM_C, USER_ID_C, DATA1, DATA2, DATA3 FROM T_USER_INFO WHERE DEL_YN = 'N' AND USER_NM_C IS NOT NULL AND USER_ID_C IS NOT NULL
AND USER_ID_C = #{userIdC}

/* com.kt.openapi.web.devsupport.dao.DevSupportDAO.selDevSupportManagerCnt */ 
SELECT  
    COUNT(*) AS cnt
FROM T_USER_INFO 
WHERE DEL_YN = 'N'

    AND USER_ID_C = #{userIdC}

mapper.update:

/* com.kt.openapi.web.devsupport.dao.DevSupportDAO.updateDevSupport */
UPDATE KOA_TB_DEVSUPPORT_BBS
SET
   TITLE = #{title}
   ,SBST = #{sbst}
   ,AMD_DT = NOW()
   ,AMDR = #{regr}
   ,DEVSUPPORT_GB = #{devSupport_GB}
   ,SERVICEINFRA_NM = #{service_BO}
   ,SERVICE_DO = #{service_DO}
   ,ADC_ID  = #{adcId}
   ,SERVICE_CODE = #{serviceCode}
WHERE PSTING_ID = #{pstingId}
